(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.02-t*0.15)*15;
  const w1y = Math.cos(y*0.018-t*0.22)*18 + Math.sin(x*0.012+t*0.28)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.35)*10 + Math.cos((y+w1y)*0.02+t*0.3)*8;
  const w2y = Math.cos((y+w1y)*0.022+t*0.32)*10 + Math.sin((x+w1x)*0.018-t*0.4)*7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+1)*60, 0.065, 2.4, 1.05],
    [200+Math.sin(t*0.38+4)*100, 220+Math.cos(t*0.58+2)*70, 0.095, 1.8, 1.0],
    [300+Math.cos(t*0.42+1)*90, 30+Math.sin(t*0.52+3)*80, 0.075, 2.2, 0.9]
  ];
  let aS = 0, iS = 0, cross = 0;
  const n = src.length;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const a = Math.sin(d*f - t*sp);
    const i = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += a * w; iS += i * w; cross += a * i * 0.3;
  }
  const act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.08+sy*0.06-t*0.5)*0.5+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.15-sy*0.08+t*1.8)*0.15)/3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
