  const rings = Math.sin(dist*0.12-t*1.8)*Math.sin(ang*5+t*0.6)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const feed = Math.tanh(act*1.5-inh*0.8)*0.4;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+rings+cross*0.2+feed)*2.0);
  const blend = reaction*0.55+cell*0.2+feed*0.15+rings*0.1;
  const v = blend*0.5+0.5;
  const pal = [[10,15,58],[12,55,95],[18,100,120],[25,155,130],[120,180,80],[210,190,60],[225,140,65],[210,95,75],[175,60,85],[120,35,90],[65,25,75],[10,15,58]];
  const hueShift = Math.sin(t*0.15)*0.04;
  const av = Math.max(0,Math.min(1,v+hueShift*Math.sin(v*Math.PI*2)));
  const idx = av*(pal.length-1), i = Math.min(idx|0,pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = 1.0+(Math.abs(reaction)>0.75?0.18:0)+(Math.abs(reaction)>0.9?0.08:0);
  const vig = 1.0-(dist/360)*0.15;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
